import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ITEM_TYPES = ['가족', '학력', '경력', '자격·면허', '외국어', '인사고과', '상벌', '출장', '부양가족', '병역', '보훈'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
// 가정: 열람 로그의 접속 구분은 웹, 열람 대상 정보 유형은 '인사기록카드'로 기록한다.
const LOG_LOGIN_TYPE = '웹';
const LOG_TARGET_INFO_TYPE = '인사기록카드';
// 가정: 엑셀 파일은 파일 이름·열 이름·행 목록을 담은 객체로 돌려주고 화면이 파일로 만든다.
const FILE_NAME = 'hr-card-items.xlsx';
const FILE_CONTENT_TYPE = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

function optionalText(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr01402Controller {
  @Get('/hr-card-items/export')
  async exportHrCardItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const itemType = optionalText(query['itemType'], '항목 유형');
    const startDate = optionalText(query['startDate'], '조회 시작일');
    const endDate = optionalText(query['endDate'], '조회 종료일');
    if (itemType !== null && !ITEM_TYPES.includes(itemType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '항목 유형이 올바르지 않습니다.');
    }
    if (startDate !== null && !DATE_PATTERN.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일 형식이 올바르지 않습니다.');
    }
    if (endDate !== null && !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      if (startDate !== null && endDate !== null) {
        const check = await db.query(
          'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS "invalid"',
          { startDate, endDate },
        );
        if (check[0] && check[0]['invalid']) {
          throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 시작일이 종료일보다 늦을 수 없습니다.');
        }
      }
      // 가정: 날짜 조건은 항목 기간(종료일 없으면 시작일)이 조회 기간과 겹치는 항목을 뜻한다.
      const rows = await db.query(
        `SELECT hr_card_item_id AS "hrCardItemId",
                employee_id AS "employeeId",
                item_type AS "itemType",
                title AS "title",
                detail AS "detail",
                start_date AS "startDate",
                end_date AS "endDate",
                related_person_name AS "relatedPersonName"
           FROM hr_card_item
          WHERE (CAST(:itemType AS varchar) IS NULL OR item_type = CAST(:itemType AS varchar))
            AND (CAST(:startDate AS date) IS NULL OR COALESCE(end_date, start_date) >= CAST(:startDate AS date))
            AND (CAST(:endDate AS date) IS NULL OR COALESCE(start_date, end_date) <= CAST(:endDate AS date))
          ORDER BY employee_id, item_type, hr_card_item_id`,
        { itemType, startDate, endDate },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NO_DATA_TO_EXPORT', '조건에 해당하는 데이터가 없습니다.');
      }
      await db.execute(
        `INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :loginIp, :loginType, :targetInfoType, now(), now())`,
        {
          userId: user.id,
          loginIp: req.ip ?? '0.0.0.0',
          loginType: LOG_LOGIN_TYPE,
          targetInfoType: LOG_TARGET_INFO_TYPE,
        },
      );
      return {
        file: {
          fileName: FILE_NAME,
          contentType: FILE_CONTENT_TYPE,
          columns: ['hrCardItemId', 'employeeId', 'itemType', 'title', 'detail', 'startDate', 'endDate', 'relatedPersonName'],
          rows,
        },
      };
    });
  }
}

