import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  DateText,
  ErrorText,
  Field,
  Filters,
  RefName,
  Select,
  DateInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

const ITEM_TYPES = ['가족', '학력', '경력', '자격·면허', '외국어', '인사고과', '상벌', '출장', '부양가족', '병역', '보훈'];

interface ExportFile {
  file: { fileName: string; columns: string[]; rows: Row[] };
}

function toCsv(columns: string[], rows: Row[]): string {
  const cell = (v: unknown) => '"' + String(v ?? '').split('"').join('""') + '"';
  const lines = [columns.map(cell).join(',')];
  rows.forEach((r) => lines.push(columns.map((c) => cell(r[c])).join(',')));
  return '\uFEFF' + lines.join('\r\n');
}

export default function FnSfr01402Page({ role, notify }: PageProps) {
  const [itemType, setItemType] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [rows, setRows] = useState<Row[]>([]);
  const [searched, setSearched] = useState(false);
  const [error, setError] = useState('');

  async function fetchRows(): Promise<ExportFile | undefined> {
    setError('');
    if (startDate && endDate && startDate > endDate) {
      setError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return undefined;
    }
    try {
      const res = await call<ExportFile>('GET', '/hr-card-items/export', role, undefined, {
        itemType,
        startDate,
        endDate,
      });
      return res;
    } catch (e) {
      setRows([]);
      setSearched(true);
      setError(e instanceof Error ? e.message : '조회에 실패했습니다.');
      return undefined;
    }
  }

  async function search() {
    const res = await fetchRows();
    if (res) {
      setRows(res.file.rows);
      setSearched(true);
    }
  }

  async function download() {
    const res = await fetchRows();
    if (!res) {
      return;
    }
    setRows(res.file.rows);
    setSearched(true);
    const blob = new Blob([toCsv(res.file.columns, res.file.rows)], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = res.file.fileName.replace('.xlsx', '.csv');
    link.click();
    URL.revokeObjectURL(url);
    notify('인사기록 현황을 내려받았습니다.');
  }

  function reset() {
    setItemType('');
    setStartDate('');
    setEndDate('');
    setRows([]);
    setSearched(false);
    setError('');
  }

  const employeeCount = new Set(rows.map((r) => String(r['employeeId']))).size;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 건수</h2>
        <Tiles
          items={[
            ['항목', rows.length],
            ['임직원', employeeCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>인사기록 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="항목 유형">
            <Select
              value={itemType}
              onChange={setItemType}
              options={ITEM_TYPES.map((t): [string, string] => [t, t])}
              placeholder="전체"
            />
          </Field>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={rows.length}>
          <button type="button" onClick={download}>엑셀 내려받기</button>
        </Band>
        <DataTable
          rows={rows}
          empty={searched ? '조회 결과가 없습니다.' : '조건을 지정하고 조회하세요.'}
          columns={[
            { key: 'employeeId', label: '임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'itemType', label: '항목 유형' },
            { key: 'title', label: '항목명' },
            { key: 'detail', label: '상세 내용' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r['startDate']} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r['endDate']} /> },
            { key: 'relatedPersonName', label: '관련자명' },
          ]}
        />
      </section>
    </div>
  );
}
